 "content": "def transform(grid):
    """Recolor every uniform row and uniform column to 2."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    uniform_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    uniform_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]
    for r in uniform_rows:
        for c in range(w):
            out[r][c] = 2
    for c in uniform_cols:
        for r in range(h):
            out[r][c] = 2
    return out
